def main():
    records=json.loads((REF/'inventory.json').read_text(encoding='utf8'))
    keys={Path(r['path']).parent.name+'/'+Path(r['path']).name for r in records}
    assert keys==set(NOTES),(keys-set(NOTES),set(NOTES)-keys)
    OUT.mkdir(parents=True,exist_ok=True)
    text=['# Каталог просмотренных артов кораблей\n',
          'Дата разбора: 2026-11-16. Все **59** файлов из `D:/work/ART_SHIP` просмотрены на обзорных листах. Ниже — наблюдения по каждому изображению; это анализ формы, а не подтверждение авторства, даты или точного соответствия retail. Источники не изменялись.\n',
          '[Правила работы с артами](art_reference_workflow.md) · [Общий разбор моделей](README.md)\n',
          'Размеры и SHA-256 каждого исходника сохранены в [inventory.json](../../../out/ship_design/references/inventory.json).\n']
    for family in ('RH','LI','BR','KU','CO','GE','NO'):
        text += [f'## {family}\n']
        for sheet in sorted(REF.glob(f'{family}_*.jpg')):
            text.append(f'[Обзорный лист {sheet.stem}](../../../out/ship_design/references/{sheet.name})\n')
        text += ['| Изображение | Наблюдение и применение |','|---|---|']
        for r in records:
            p=Path(r['path']);key=p.parent.name+'/'+p.name
            if p.parent.name!=family:continue
            text.append(f'| [{p.name}](<{p.as_posix()}>) ({r["size"][0]}×{r["size"][1]}) | {NOTES[key]} |')
        text.append('')
    text += ['## Отдельно: созданный концепт B\n',
      '[rh_concept_B.png](../../../out/ship_design/rh_elite/concepts/rh_concept_B.png) — новый согласованный ориентир, не исходный арт Freelancer. В нём важны толстая восьмигранная рама, просветы вокруг ступицы, полноценная задняя часть кабины, силовая шея и короткие массивные крылья. Не воспроизводить декоративные заклёпки.\n',
      'Первоначальный текст генерации упоминал складывание inward/upward. Последнее указание пользователя его заменяет: **вперёд и к корпусу, не вверх**. При конфликте видов на концепте сначала фиксируется единая механическая схема.\n']
    (OUT/'art_catalog.md').write_text('\n'.join(text),encoding='utf8')
    print('59 artwork observations ->',OUT/'art_catalog.md')

if __name__=='__main__':main()
